/**
 * Prebundle fleet Edge Functions for `--use-api` deploy (5 MB source cap).
 * See docs/fleet-edge-5mb-split-plan.md Phase A0.
 *
 * Usage:
 *   node scripts/build-edge-bundle.mjs              # make-server only
 *   node scripts/build-edge-bundle.mjs --all         # all TARGETS with existing entry
 *   node scripts/build-edge-bundle.mjs fleet-fuel
 */
import * as esbuild from "esbuild";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");

const REMOTE_PREFIXES = ["npm:", "jsr:", "node:", "https:", "http:", "data:"];

/** Mark Deno remote / npm / node specifiers external so the edge runtime resolves them. */
const externalRemotePlugin = {
  name: "external-remote-specifiers",
  setup(build) {
    build.onResolve({ filter: /.*/ }, (args) => {
      if (REMOTE_PREFIXES.some((p) => args.path.startsWith(p))) {
        return { path: args.path, external: true };
      }
      return null;
    });
  },
};

const TARGETS = {
  "make-server-37f42386": {
    entry: path.join(ROOT, "supabase/functions/_fleet-server/index.tsx"),
    outfile: path.join(ROOT, "supabase/functions/make-server-37f42386/index.ts"),
  },
  "fleet-fuel": {
    entry: path.join(ROOT, "supabase/functions/fleet-fuel/src/main.ts"),
    outfile: path.join(ROOT, "supabase/functions/fleet-fuel/index.ts"),
  },
  "fleet-toll": {
    entry: path.join(ROOT, "supabase/functions/fleet-toll/src/main.ts"),
    outfile: path.join(ROOT, "supabase/functions/fleet-toll/index.ts"),
  },
  "fleet-ops": {
    entry: path.join(ROOT, "supabase/functions/fleet-ops/src/main.ts"),
    outfile: path.join(ROOT, "supabase/functions/fleet-ops/index.ts"),
  },
  "fleet-claims": {
    entry: path.join(ROOT, "supabase/functions/fleet-claims/src/main.ts"),
    outfile: path.join(ROOT, "supabase/functions/fleet-claims/index.ts"),
  },
  "fleet-pay": {
    entry: path.join(ROOT, "supabase/functions/fleet-pay/src/main.ts"),
    outfile: path.join(ROOT, "supabase/functions/fleet-pay/index.ts"),
  },
};

async function buildOne(name) {
  const target = TARGETS[name];
  if (!target) throw new Error(`Unknown edge bundle target: ${name}`);
  if (!fs.existsSync(target.entry)) {
    throw new Error(`Entry missing for ${name}: ${target.entry}`);
  }

  fs.mkdirSync(path.dirname(target.outfile), { recursive: true });

  const result = await esbuild.build({
    entryPoints: [target.entry],
    outfile: target.outfile,
    bundle: true,
    format: "esm",
    platform: "neutral",
    target: "esnext",
    minify: true,
    keepNames: true,
    sourcemap: false,
    legalComments: "none",
    banner: {
      js: "// GENERATED by scripts/build-edge-bundle.mjs — do not edit.\n",
    },
    plugins: [externalRemotePlugin],
    logLevel: "info",
    write: true,
    metafile: true,
  });

  const bytes = fs.statSync(target.outfile).size;
  const mb = (bytes / (1024 * 1024)).toFixed(3);
  console.log(`[build-edge-bundle] ${name}: ${mb} MB (${bytes} bytes) → ${path.relative(ROOT, target.outfile)}`);

  if (bytes > 5 * 1024 * 1024) {
    console.error(`[build-edge-bundle] ${name} exceeds 5 MB — deploy will 413`);
    process.exitCode = 1;
  }

  if (result.warnings?.length) {
    console.error(
      `[build-edge-bundle] ${name}: ${result.warnings.length} warning(s) — treating as failure`,
    );
    for (const w of result.warnings.slice(0, 20)) {
      console.error(" ", w.text || w);
    }
    process.exitCode = 1;
  }

  if (result.errors?.length) {
    process.exitCode = 1;
  }
}

const args = process.argv.slice(2).filter((a) => a !== "--");
let names;
if (args.includes("--all")) {
  names = Object.keys(TARGETS).filter((n) => fs.existsSync(TARGETS[n].entry));
} else if (args.length === 0) {
  names = ["make-server-37f42386"];
} else {
  names = args;
}

for (const name of names) {
  await buildOne(name);
}
